<?php
namespace App\Services;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
class CustomReportService{public const SOURCES=['students'=>['table'=>'students','columns'=>['id','admission_no','first_name','last_name','gender','status','created_at']],'staff'=>['table'=>'staff','columns'=>['id','staff_id_no','first_name','last_name','joining_date','basic_salary','is_active']],'payments'=>['table'=>'payments','columns'=>['id','student_id','amount_paid','payment_date','payment_method','transaction_id']],'expenses'=>['table'=>'expenses','columns'=>['id','expense_head','amount','expense_date','description']],'student_attendance'=>['table'=>'student_attendances','columns'=>['id','student_id','attendance_date','status','is_excused']]];
 public function rows(object|array$report){$r=(object)$report;$source=self::SOURCES[$r->data_source]??null;if(!$source)throw ValidationException::withMessages(['data_source'=>'Unsupported report source.']);$columns=is_string($r->columns)?json_decode($r->columns,true):$r->columns;$columns=array_values(array_intersect($columns,$source['columns']));if(!$columns)throw ValidationException::withMessages(['columns'=>'Choose at least one allowed column.']);$q=DB::table($source['table'])->select($columns);if(\Illuminate\Support\Facades\Schema::hasColumn($source['table'],'campus_id')&&config('app.active_campus_id'))$q->where('campus_id',config('app.active_campus_id'));$filters=is_string($r->filters??null)?json_decode($r->filters,true):($r->filters??[]);foreach($filters as$f){if(!in_array($f['column']??'', $source['columns'])||!in_array($f['operator']??'=',['=','!=','>','>=','<','<=','like']))continue;$q->where($f['column'],$f['operator'],$f['value']??null);}return$q->limit(10000)->get();}
 public function csv($rows):string{if($rows->isEmpty())return"No data\n";$h=fopen('php://temp','r+');fputcsv($h,array_keys((array)$rows->first()));foreach($rows as$row)fputcsv($h,(array)$row);rewind($h);return stream_get_contents($h);}}
